#!/bin/bash
# make_boards.sh <final hair tag label e.g. g11rlHC> <final tag text e.g. h47a> : L report boards 01-08. Labels carry the candidate id and the provenance read time from prov/<label>.json.
set -u; cd "/c/Users/berat/OneDrive/Documents/Unreal Projects/ActionAdventureMovementS"; HF=${1:?final hair label}; HT=${2:?final hair tag}; PY="/c/Program Files/Epic Games/UE_5.8/Engine/Binaries/ThirdParty/Python3/Win64/python.exe"; LB=Tools/CharacterLookdev_20260930/lk_board.py
L="$(cygpath -w "$(pwd)/Saved/Codex/GD11_HeadRefinementL_20261005")"; TR="$(cygpath -w "$(pwd)/Saved/Codex/CharacterIdentity_20260930/track")"; B="$L\\public_report\\boards"; PV="$L\\pv"; CL="$L\\pv\\clay"; CR="$L\\pv\\crop"; PN="$L\\pv\\panel"
pt() { "$PY" -c "import json; d=json.load(open('Saved/Codex/GD11_HeadRefinementL_20261005/prov/$1.json')); print(d['read_at'][11:16])"; }
A="g11rlHA"; AL="F4ab+h45b J-bind prov $(pt g11rlHA)"; HB="g11rlHB"; BL="F4ab+h46a K-bind(f4ab) prov $(pt g11rlHB)"; HC="$HF"; CLB="F4ab+$HT L-bind prov $(pt $HF)"; BR="g11rlBROW"; BRL="F4ab+h45b prov $(pt g11rlBROW)"
"$PY" $LB "$B\\01_VERIFIED_START.jpg" "GD11 L - 01 verified start: F4ab face + MHC_G11RD_F4AB_Head DNA + h45b (GB_G11RJ_*_f4abh45b) + k10. Every cell: composition read from the editor (prov/g11rlHA.json). Studio light - neutral rig - no animation" 520 "${A}_front_custom.png|front - $AL, ${A}_q3R_custom.png|3/4 R - $AL, ${A}_q3L_custom.png|3/4 L - $AL, ${A}_profR_custom.png|profile R - $AL, ${A}_profL_custom.png|profile L - $AL, ${A}_back_custom.png|back - $AL" "$TR\\ref_front_x4.png|reference front (Tier A), $TR\\ref_close_x2.png|reference 3/4 (Tier A), ${A}_rear3qR_custom.png|rear 3/4 R - $AL, ${A}_rear3qL_custom.png|rear 3/4 L - $AL, ${A}_topfront_custom.png|top-front - $AL, ${A}_top_custom.png|top - $AL"
"$PY" $LB "$B\\02_ROOT_DIAGNOSIS.jpg" "GD11 L - 02 glabella-radix-upper dorsum diagnosis. Row 1: reference crops vs F4ab textured nose root WITH / WITHOUT the brow groom (studio, grazing, balanced front light). Row 2: clay root crops: F4ab | L2 (deeper radix, rejected direction) | L4 (sidewall +0.44 mm, below visibility) and profile crops. Row 3: profile plot + heat maps + reference frames" 600 "$CR\\ref_close_root.png|reference 3/4 root crop, ${BR}_studio_noseroot_custom.png|$BRL studio with brow, ${BR}_studio_noseroot_nobrow_custom.png|$BRL studio NO brow, ${BR}_grazing_noseroot_custom.png|$BRL grazing with brow, ${BR}_grazing_noseroot_nobrow_custom.png|$BRL grazing NO brow, ${BR}_front_fcq3_nobrow_custom.png|$BRL balanced light 3/4 NO brow" "$CR\\head_F4ab_q3R_root.png|F4ab clay root 3/4, $CR\\head_L2_q3R_root.png|L2 clay (radix -2.9 mm) REJECTED direction, $CR\\head_L4_q3R_root.png|L4 clay (sidewall +0.44 mm) not visible, $CR\\head_F4ab_profR_root.png|F4ab clay profile, $CR\\head_L2_profR_root.png|L2 profile, $CR\\head_L4_profR_root.png|L4 profile" "$PV\\radix_profile.png|midline profile y(z): F4ab white - L1 orange - L2 cyan - K5 green, $PV\\heat_L2_q3R.png|L2 displacement heat (0..2 mm), $PV\\heat_L4_q3R.png|L4 displacement heat (0..1 mm), $CR\\ref_front_root.png|reference front root crop, ${BR}_front_noseroot_custom.png|$BRL balanced light with brow, ${BR}_front_noseroot_nobrow_custom.png|$BRL balanced light NO brow"
"$PY" $LB "$B\\03_FACE_BEFORE_AFTER.jpg" "GD11 L - 03 face before/after: NO face geometry change this round (F4ab kept). Row 1 = F4ab start (h45b). Row 2 = same F4ab captured later in the chain (h45b, brow diagnosis set) - identical geometry; shown so that the absence of change is explicit" 520 "${A}_front_custom.png|F4ab - $AL, ${A}_q3R_custom.png|3/4 R, ${A}_q3L_custom.png|3/4 L, ${A}_profR_custom.png|profile R, ${A}_profL_custom.png|profile L" "${BR}_studio_fcfront_custom.png|F4ab face front - $BRL, ${BR}_studio_fcq3_custom.png|face 3/4, ${BR}_front_fcq3_custom.png|face 3/4 balanced light, ${BR}_studio_fcprofR_custom.png|face profile, ${BR}_grazing_fcq3_custom.png|face 3/4 grazing"
"$PY" $LB "$B\\04_PROTECTED_REGIONS.jpg" "GD11 L - 04 protected regions: displacement heat of the evaluated (not adopted) root candidates vs F4ab - chin, mouth, cheeks, eyes, nose base all 0.00 mm (eyes/lids <= 0.28 mm in L2). Grey = 0, yellow = half ramp, red = full ramp" 560 "$PV\\heat_L1_front.png|L1 front (0..2 mm), $PV\\heat_L1_q3R.png|L1 3/4, $PV\\heat_L1_profR.png|L1 profile, $PV\\heat_L2_front.png|L2 front (0..2 mm), $PV\\heat_L2_q3R.png|L2 3/4, $PV\\heat_L2_profR.png|L2 profile" "$PV\\heat_L3_front.png|L3 front (0..1 mm), $PV\\heat_L3_q3R.png|L3 3/4, $PV\\heat_L3_profR.png|L3 profile, $PV\\heat_L4_front.png|L4 front (0..1 mm), $PV\\heat_L4_q3R.png|L4 3/4, $PV\\heat_L4_profR.png|L4 profile"
"$PY" $LB "$B\\05_HAIR_COMPARISON.jpg" "GD11 L - 05 hair on the SAME F4ab + k10, same cameras/light: h45b | h46a | $HT. Each label = composition read from the editor at capture time" 520 "${A}_front_custom.png|front - $AL, ${HB}_front_custom.png|front - $BL, ${HC}_front_custom.png|front - $CLB, ${A}_q3R_custom.png|3/4 R - $AL, ${HB}_q3R_custom.png|3/4 R - $BL, ${HC}_q3R_custom.png|3/4 R - $CLB" "${A}_q3L_custom.png|3/4 L - $AL, ${HB}_q3L_custom.png|3/4 L - $BL, ${HC}_q3L_custom.png|3/4 L - $CLB, ${A}_profR_custom.png|profile R - $AL, ${HB}_profR_custom.png|profile R - $BL, ${HC}_profR_custom.png|profile R - $CLB" "${A}_profL_custom.png|profile L - $AL, ${HB}_profL_custom.png|profile L - $BL, ${HC}_profL_custom.png|profile L - $CLB, ${A}_back_custom.png|back - $AL, ${HB}_back_custom.png|back - $BL, ${HC}_back_custom.png|back - $CLB"
"$PY" $LB "$B\\06_NAPE_EAR_TEMPLE.jpg" "GD11 L - 06 nape, behind-ear and crossing temple flow: h45b | h46a | $HT (close-ups + whole head, rear light sets)" 520 "${A}_cuHairline3q_s_custom.png|hairline 3/4 - h45b, ${HB}_cuHairline3q_s_custom.png|hairline 3/4 - h46a, ${HC}_cuHairline3q_s_custom.png|hairline 3/4 - $HT, ${A}_tmR_s_custom.png|temple R - h45b, ${HB}_tmR_s_custom.png|temple R - h46a, ${HC}_tmR_s_custom.png|temple R - $HT" "${A}_cuEarR_s_custom.png|ear R - h45b, ${HB}_cuEarR_s_custom.png|ear R - h46a, ${HC}_cuEarR_s_custom.png|ear R - $HT, ${A}_earR_lit_custom.png|ear R rear light - h45b, ${HB}_earR_lit_custom.png|ear R rear light - h46a, ${HC}_earR_lit_custom.png|ear R rear light - $HT" "${A}_cuRear3qR_s_custom.png|nape close - h45b, ${HB}_cuRear3qR_s_custom.png|nape close - h46a, ${HC}_cuRear3qR_s_custom.png|nape close - $HT, ${A}_rear3qR_lit_custom.png|rear 3/4 lit - h45b, ${HB}_rear3qR_lit_custom.png|rear 3/4 lit - h46a, ${HC}_rear3qR_lit_custom.png|rear 3/4 lit - $HT" "${A}_bun_lit_custom.png|bun rear light - h45b, ${HB}_bun_lit_custom.png|bun - h46a, ${HC}_bun_lit_custom.png|bun - $HT, $PN\\g_h45b_profR_loose.png|h45b loose families (strand geometry), $PN\\g_h46a_profR_loose.png|h46a loose families, $PN\\g_h47a_profR_loose.png|h47a loose families"
"$PY" $LB "$B\\07_SEPARATION.jpg" "GD11 L - 07 separation: start (F4ab+h45b) | face only: none (no face change adopted) | hair only ($HT on F4ab) | combined = hair only" 560 "${A}_front_custom.png|start - $AL, ${A}_front_custom.png|face only = start (no change), ${HC}_front_custom.png|hair only - $CLB, ${HC}_front_custom.png|combined = hair only" "${A}_q3R_custom.png|start 3/4, ${A}_q3R_custom.png|face only = start, ${HC}_q3R_custom.png|hair only, ${HC}_q3R_custom.png|combined" "${A}_profR_custom.png|start profile, ${A}_profR_custom.png|face only = start, ${HC}_profR_custom.png|hair only, ${HC}_profR_custom.png|combined"
"$PY" $LB "$B\\08_TECHNICAL.jpg" "GD11 L - 08 technical (F4ab + $HT, L bindings): rig expressions (hair hidden) - motion - pitch - after clean restart - LOD distance 1.25..25 m" 440 "g11rlrig_neutral_3q_custom.png|neutral, g11rlrig_blink_3q_custom.png|blink, g11rlrig_look_left_3q_custom.png|look L, g11rlrig_brows_up_3q_custom.png|brows up, g11rlrig_smile_3q_custom.png|smile, g11rlrig_lips_closed_3q_custom.png|lips closed, g11rlrig_jaw_open_3q_custom.png|jaw open, g11rlrig_ph_oo_3q_custom.png|viseme oo" "g11rlrig_upper_lip_raise_3q_custom.png|upper lip raise, g11rlrig_sneer_3q_custom.png|sneer, g11rlrig_nostril_dilate_front_custom.png|nostril dilate, g11rlmot_look10_side_custom.png|look 1.0s, g11rlmot_look55_side_custom.png|look 5.5s, g11rlmot_turnL06_back_custom.png|turn L, g11rlmot_stop06_q3_custom.png|stop, g11rlafter_front_custom.png|after restart" "g11rlP_pitchDn_side_custom.png|pitch down, g11rlP_pitchDn_back_custom.png|pitch down back, g11rlP_pitchUp_q3_custom.png|pitch up, g11rlafter_rear3qR_custom.png|after restart rear 3/4, $PN\\lod_f_125.png|front 1.25 m, $PN\\lod_f_600.png|6 m, $PN\\lod_f_1200.png|12 m, $PN\\lod_f_2500.png|25 m"
ls -la "Saved/Codex/GD11_HeadRefinementL_20261005/public_report/boards"
